import de.mrjulsen.mcdragonlib.client.gui.widgets.components.DLRichTextEditBox;
import de.mrjulsen.mcdragonlib.client.gui.widgets.richtext.RichTextComponent;
import de.mrjulsen.mcdragonlib.client.gui.widgets.richtext.autocomplete.DLAutocompleteWindow;
import de.mrjulsen.mcdragonlib.client.gui.widgets.richtext.autocomplete.IAutocompletionManager;
import de.mrjulsen.mcdragonlib.network.NetworkDirection;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.function.Supplier;
import net.minecraft.client.Minecraft;

public class StationsAutocomplete
implements IAutocompletionManager<String> {
    private final List<String> names = new ArrayList<String>();
    private final Supplier<List<String>> ignoreList;

    public StationsAutocomplete(Supplier<List<String>> ignoreList) {
        this.ignoreList = ignoreList;
    }

    public DLAutocompleteWindow<String> createWindow(DLWindowManager windowManager, DLRichTextEditBox textBox) {
        DLAutocompleteWindow window = super.createWindow(windowManager, textBox);
        ModNetworkManager.GET_ALL_STATION_NAMES.send((NetworkDirection)NetworkDirection.toServer(), result -> Minecraft.m_91087_().execute(() -> {
            ArrayList<String> filteredNames = new ArrayList<String>(result.getStations());
            filteredNames.removeAll((Collection)this.ignoreList.get());
            this.names.clear();
            this.names.addAll(filteredNames.stream().distinct().sorted(String::compareToIgnoreCase).toList());
            this.configureWindow((DLAutocompleteWindow<String>)window, textBox);
        }), () -> {});
        return window;
    }

    public void configureWindow(DLAutocompleteWindow<String> window, DLRichTextEditBox textBox) {
        window.suggestions.set(this.names);
        window.filter.set(tag -> tag.toLowerCase().contains(((RichTextComponent)textBox.text.get()).getPlainText().toLowerCase()));
    }

    public void closeWindow(DLAutocompleteWindow<String> window, DLRichTextEditBox textBox) {
        this.names.clear();
        super.closeWindow(window, textBox);
    }
}

